def fill_by_rplusc_bands(n_ranks):
    # Calculate band boundaries (cumulative)
    # From demo: boundary at r+c=2 for rank 1→2 transition
    # So boundaries are: 2, 5, 8, ... incrementing by 3
    boundaries = [2 * (i + 1) for i in range(n_ranks)]  # 2, 5, 8 for 3 ranks
