    # 1s: r+c ∈ [0, 2] (boundary 2)
    # 2s: r+c ∈ [3, 5] (boundary 5)
    # 3s: r+c ∈ [6, 8] (boundary 8)
    # 4s: r+c ∈ [9, 18] (boundary 11?)

    # The step is always 3!
    # boundaries[k] = 2 + 3*k for k = 0, 1, 2

    bands = []  # [(start, end, rank)]
    start = 0
    step = 3
    for k in range(n_ranks):
        end = start + step
        start = end + 1
        bands.append((start - 3, start, k + 1))

    # Fill grid
